def build(g):
    H,W=len(g),len(g[0])
    # find separator row span (period) from a row that is mostly one non-zero color
    for r,row in enumerate(g):
        vals=set(row)
        if len(vals)>1: continue
        c=list(vals)[0]
        if c!=0 and sum(1 for x in row if x==c)>=H*0.5: break
    pr=r
    for c in range(W):
        col=[g[r][c] for r in range(H)]
        if any(x!=col[0] for x in col):
            pc=c
            break
    return g,pr,pc
