    return G
G=load()

def line_colors(a):
    H,W=a.shape; th=0.9*max(H,W); seen=set(); 
    for c in Counter(a.flatten()).items():
        cc=c[0]
        maxrun=0
        # vertical runs
        for j in range(W):
            prev=None; k=0
            for i in range(H):
                if a[i,j]==cc:
                    k+=1; prev=(i-k,k)
                    if k>maxrun: maxrun=max(maxrun,k)
                else:
                    if k>maxrun: maxrun=max(maxrun,k)
                    k=0
            if k>maxrun: maxrun=max(maxrun,k)
        if maxrun>=th: seen.add(cc)
    return sorted(seen)

def solve(g):
    a=np.array(g); H,W=a.shape
    bg=Counter(a.flatten()).most_common(1)[0][0]
    lc=line_colors(a)
    vals={bg}|set(lc)
    mr=[i for i in range(H) if any(a[i,j] not in vals for j in range(W))]
    mc=[j for j in range(W) if any(a[i,j] not in vals for i in range(H))]
    res=[]
    for i in range(len(mr)-1):
        row=[]
        for k in range(len(mc)-1):
            c1,c2=mc[k],mc[k+1]
            cs=[int(a[mr[i],c1]),int(a[mr[i],c2]),int(a[mr[i+1],c1]),int(a[mr[i+1],c2])]
            row.append(cs[0] if len(set(cs))==1 else 0)
        res.append(row)
    return res

